import React, { useState, useEffect } from "react";
import MapView from "./MapView";
import CrimeStats from "./CrimeStats";
import Filters from "./Filters";

const App = () => {
  const [crimes, setCrimes] = useState([]);
  const [filter, setFilter] = useState(""); // only CrimeCode filter

  // Fetch crime data
  useEffect(() => {
    fetch("http://127.0.0.1:5000/api/crimes")
      .then((res) => res.json())
      .then((data) => setCrimes(data))
      .catch((err) => console.error(err));
  }, []);

  // Filter crimes by CrimeCode
  const filteredCrimes = filter
    ? crimes.filter((c) => c.CrimeCode === filter)
    : crimes;

  // Build options dynamically
  const crimeOptions = [...new Set(crimes.map((c) => c.CrimeCode))];

  return (
    <div style={{ display: "flex", height: "100vh" }}>
      {/* Left panel: Filters + Map */}
      <div style={{ flex: 2, display: "flex", flexDirection: "column" }}>
        <div style={{ padding: "10px", backgroundColor: "#f0f0f0" }}>
          <Filters filter={filter} setFilter={setFilter} options={crimeOptions} />
        </div>
        <div style={{ flex: 1 }}>
          <MapView crimes={filteredCrimes} />
        </div>
      </div>

      {/* Right panel: Crime Stats */}
      <div style={{ flex: 1, padding: "20px", overflowY: "auto", backgroundColor: "#fafafa" }}>
        <CrimeStats crimes={filteredCrimes} />
      </div>
    </div>
  );
};

export default App;
